INSERT INTO reviews (author, review_date, stars, body, is_featured, position) VALUES ('Isabelle', '10.09.2025', 5, 'Au départ un peu sceptique, mais après quelques minutes de discussion avec Edan, le courant est très bien passé. Il ne force pas à la vente, répond sans détour à nos questions. La voiture nous a été livrée dans un état impeccable, encore plus belle que la première fois.', 1, 4);
INSERT INTO reviews (author, review_date, stars, body, is_featured, position) VALUES ('MEGALI Gauthier', '30.06.2025', 5, 'Très satisfait de notre achat ! Le véhicule est conforme à l''annonce, en excellent état. Le vendeur a été très sympa, disponible et transparent tout au long du processus.', 1, 5);
INSERT INTO reviews (author, review_date, stars, body, is_featured, position) VALUES ('Selin', '12.04.2025', 5, 'We zijn zeer tevreden met onze aankoop bij deze verkoper. Hij was vriendelijk, gaf genoeg en gepaste uitleg. We raden deze verkoper zeker aan!', 0, 6);
